  'Operations starter': ['Operations starter', 'Pengenalan operasi', '运营入门', '營運入門', '운영 입문', 'செயல்பாடுகள் தொடக்கம்', 'オペレーション入門', 'Dasar operasional'],
  '3 — Working knowledge': ['3 — Working knowledge', '3 — Pengetahuan kerja', '3 — 熟练使用', '3 — 熟練使用', '3 — 실무 지식', '3 — பணித்திறன் அறிவு', '3 — 実務知識', '3 — Pengetahuan kerja'],
